import Component from '@glimmer/component';
import { precompileTemplate } from '@ember/template-compilation';
import { setComponentTemplate } from '@ember/component';

class PolyText extends Component {
  get componentTag() {
    const {
      tag = 'span'
    } = this.args;
    return tag;
  }
  static {
    setComponentTemplate(precompileTemplate("{{#let (element this.componentTag) as |Tag|}}<Tag ...attributes>{{yield}}</Tag>{{/let}}", {
      strictMode: true,
      scope: () => ({})
    }), this);
  }
}

export { PolyText as default };
